CREATE TABLE IF NOT EXISTS care_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_key text UNIQUE NOT NULL, patient_name text NOT NULL, source_name text NOT NULL DEFAULT '', source_date text NOT NULL DEFAULT '', effective_date text NOT NULL DEFAULT '', content jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT '草稿', updated_at timestamptz NOT NULL DEFAULT now(), updated_by text NOT NULL DEFAULT '')